SELECT pioi.inbound_order_id AS inboundOrderId, GROUP_CONCAT(CONCAT(pioi.sku_code, '×', pioi.actual_quantity) SEPARATOR ', ') AS itemSummary, SUM(pioi.expected_quantity) AS totalExpectedQty, SUM(pioi.actual_quantity) AS totalActualQty, SUM(pioi.expected_quantity - pioi.actual_quantity) AS totalShortQty, COUNT(DISTINCT pioi.sku_code) AS skuCount FROM wms_purchase_inbound_order_item pioi WHERE pioi.inbound_order_id IN
#{orderId}
GROUP BY pioi.inbound_order_id

SELECT pioi.inbound_order_id AS inboundOrderId, po.order_no AS purchaseOrderNo FROM wms_purchase_inbound_order_item pioi INNER JOIN wms_purchase_order po ON pioi.purchase_order_id = po.id WHERE pioi.inbound_order_id IN
#{orderId}
GROUP BY pioi.inbound_order_id, po.order_no ORDER BY pioi.inbound_order_id, po.order_no
